def isAnagram(s, t):
    if len(s) != len(t):
        return False
    # Count chars: increment for s, decrement for t
    count = {}
    for i in range(len(s)):
        count[s[i]] = count.get(s[i], 0) + 1
        count[t[i]] = count.get(t[i], 0) - 1
    return all(v == 0 for v in count.values())

