def groupAnagrams(strs):
    groups = {}  # sorted_str -> [original strings]
    for s in strs:
        key = tuple(sorted(s))  # or ''.join(sorted(s))
        groups.setdefault(key, []).append(s)
    return list(groups.values())

# Alt: O(N*K) using char count as key (K=max word length)
def groupAnagrams(strs):
    groups = {}
    for s in strs:
        count = [0] * 26
        for c in s:
            count[ord(c) - ord('a')] += 1
        groups.setdefault(tuple(count), []).append(s)
    return list(groups.values())

