def topKFrequent(nums, k):
    count = {}
    for n in nums:
        count[n] = count.get(n, 0) + 1

    # Bucket sort: index = frequency, value = list of nums
    buckets = [[] for _ in range(len(nums) + 1)]
    for num, freq in count.items():
        buckets[freq].append(num)

    # Collect from highest frequency bucket
    result = []
    for i in range(len(buckets) - 1, -1, -1):
        for num in buckets[i]:
            result.append(num)
            if len(result) == k:
                return result

code.cpp:
class Solution {
public:
    vector<int> topKFrequent(vector<int>& nums, int k) {
        unordered_map<int, int> freq;
        for (int n : nums) freq[n]++;
        vector<vector<int>> bucket(nums.size() + 1);
        for (auto& [num, cnt] : freq) bucket[cnt].push_back(num);
        vector<int> result;
        for (int i = bucket.size() - 1; i >= 0 && result.size() < k; i--)
            for (int n : bucket[i]) {
                result.push_back(n);
                if (result.size() == k) break;
            }
        return result;
    }
};

code.java:
class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int n : nums) freq.merge(n, 1, Integer::sum);
        List<Integer>[] bucket = new List[nums.length + 1];
        for (int i = 0; i < bucket.length; i++) bucket[i] = new ArrayList<>();
        for (var e : freq.entrySet()) bucket[e.getValue()].add(e.getKey());
        int[] result = new int[k];
        int idx = 0;
        for (int i = bucket.length - 1; i >= 0 && idx < k; i--)
            for (int n : bucket[i]) { result[idx++] = n; if (idx == k) break; }
        return result;
    }
}

code.js:
var topKFrequent = function(nums, k) {
    const freq = new Map();
    for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);
    const bucket = Array.from({length: nums.length + 1}, () => []);
    for (const [num, cnt] of freq) bucket[cnt].push(num);
    const result = [];
    for (let i = bucket.length - 1; i >= 0 && result.length < k; i--)
        result.push(...bucket[i]);
    return result.slice(0, k);
};

